<?php
declare(strict_types=1);require_once __DIR__.'/includes/layout.php';login_required();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=post_int('id');if(post('action')==='delete'&&$id){$pdo->prepare('DELETE FROM employee WHERE employee_id=?')->execute([$id]);flash('success','Employee deleted.');}redirect('employees.php');}
$rows=$pdo->query('SELECT e.*,d.department_name FROM employee e LEFT JOIN department d ON d.department_id=e.department_id ORDER BY e.employee_id')->fetchAll();page_header('Employees','employee');?>
<div class="page-head"><h1>Employees</h1><a class="btn primary" href="employee_form.php">Add Employee</a></div><section class="card table-wrap"><table><thead><tr><th>ID</th><th>Fullname</th><th>Username</th><th>Department</th><th>Job</th><th>Email</th><th>Telephone</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['employee_id']?></td><td><?=e($r['employee_firstname'].' '.$r['employee_lastname'])?></td><td><?=e($r['employee_username'])?></td><td><?=e($r['department_name']??'')?></td><td><?=e($r['employee_type'])?></td><td><?=e($r['employee_email'])?></td><td><?=e($r['employee_telephone'])?></td><td class="actions"><a href="employee_form.php?id=<?=$r['employee_id']?>">Edit</a><form method="post" onsubmit="return confirm('Are you sure?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['employee_id']?>"><button class="danger-link">Delete</button></form></td></tr><?php endforeach;?></tbody></table></section><?php page_footer();?>
